"""Create and read back a complete current-source ZIP with per-member SHA-256."""
from pathlib import Path
import hashlib, json, zipfile, sys
ROOT=Path(__file__).resolve().parents[1]
archive=ROOT.parent/'Tau_Fixed_Period_Exterior_Continuation_2026-09-15.zip'
def sha(data):return hashlib.sha256(data).hexdigest()
# The manifest excludes itself. Archive verification is external because it hashes the ZIP.
skip={'MANIFEST.json','ARCHIVE_VERIFICATION.json'}
files=[p for p in ROOT.rglob('*') if p.is_file() and p.relative_to(ROOT).as_posix() not in skip and '__pycache__' not in p.parts]
entries=[{'path':p.relative_to(ROOT).as_posix(),'bytes':p.stat().st_size,'sha256':sha(p.read_bytes())}
         for p in sorted(files)]
manifest={'format':'SHA-256','scope':'all listed current inputs, new proofs, receivers, source/evidence and explicitly unreviewed separate lane',
          'self_excluded':True,'entries':entries}
(ROOT/'MANIFEST.json').write_text(json.dumps(manifest,indent=2)+'\n')
with zipfile.ZipFile(archive,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=7) as z:
    for item in entries:
        z.write(ROOT/item['path'],arcname=ROOT.name+'/'+item['path'])
    z.write(ROOT/'MANIFEST.json',arcname=ROOT.name+'/MANIFEST.json')
with zipfile.ZipFile(archive) as z:
    bad=z.testzip()
    if bad:raise RuntimeError('ZIP CRC failure: '+bad)
    for item in entries:
        data=z.read(ROOT.name+'/'+item['path'])
        if len(data)!=item['bytes'] or sha(data)!=item['sha256']:
            raise RuntimeError('Archived bytes differ: '+item['path'])
    manifest_read=json.loads(z.read(ROOT.name+'/MANIFEST.json'))
    if manifest_read!=manifest:raise RuntimeError('Archive manifest mismatch')
    members=len(z.infolist())
receipt={'archive':str(archive),'bytes':archive.stat().st_size,'sha256':sha(archive.read_bytes()),
         'zip_members':members,'verified_file_hashes':len(entries),'manifest_readback':True,'crc_test':'passed',
         'new_pdfs_included':['proof/FIXED_PERIOD_EXTERIOR_RETURN.pdf','receivers/09_UPDATED_JOINT_NOTE_FEX.pdf','receivers/10_UPDATED_SIGNED_RETURN_FEX.pdf'],
         'all_17_current_input_files_included':True,'unreviewed_previous_lane_explicitly_labelled':True}
(ROOT/'ARCHIVE_VERIFICATION.json').write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps(receipt,indent=2))

