\[
 \mathcal T_k^{(s)}
  =\sum_N\sigma_N\left[
      \sum_{n=N-v+1}^{N}\log h_n
      +\log D_{t+\Delta-v}(P_{k'};s)
      -\log D_t(P_k;s)\right].
