 {\left(\prod_{n=q}^{q+l-1}\omega_n^\sigma\right)\det A_{q+l-1}},
 \quad
 \Delta_f=2^{l(l-1)/2}\prod_{r=1}^{l-1}r!.
 \label{eq:first}
