\[
 (Cx)_j=x_{j+1}-x_1\quad(1\leq j<N-1),\qquad
 (Cx)_{N-1}=-x_1.
 \tag{OCS4}
\]
Set $\zeta=\exp(2\pi i/N)$ and, for $1\leq t\leq N-1$, let
