\[
 C_{A,D,s}=\frac{v!}{|\mu_v|}\,
  e^{4(H_D+2)}N_{D,s}\,
  2^v(D+1)\alpha_{D,s}\max\{1,b^{v/2}\}.
 \tag{AIE22}
\]
